INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT144-S4-Q11$batch09$, 144, 4, 11, $batch09$Principle-Conform$batch09$, $batch09$A person who knowingly brings about misfortune should be blamed for it. However, in some cases a person who unwittingly brings about misfortune should not be blamed for it. For example, a person should never be blamed for unwittingly bringing about misfortune if the person could not reasonably have foreseen it.$batch09$, $batch09$The principles above, if valid, most help to justify the reasoning in which one of the following?$batch09$, $batch09$B$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=144 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT144-S4-Q11$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$Although he would have realized it if he had thought about it, it did not occur to Riley that parking his car in the center lane of Main Street could lead to a traffic accident. So, if a traffic accident does result from Riley’s parking his car in the center lane of Main Street, he should not be blamed for it.$batch09$, $batch09$Rule Not Triggered$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT144-S4-Q11$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$Oblicek had no idea that suggesting to her brother that he take out a loan to expand his business was likely to cause the business to go bankrupt, nor could she have reasonably foreseen this. So, if the loan does cause her brother’s business to go bankrupt, Oblicek should not be blamed for it.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT144-S4-Q11$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$Gougon had no reason to think that serving the hollandaise sauce would make his guests ill, but he was concerned that it might. Thus, if the hollandaise sauce does make Gougon’s guests ill, Gougon should be blamed for it.$batch09$, $batch09$Rule Not Triggered$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT144-S4-Q11$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$When Dr. Fitzpatrick gave his patient the wrong medicine, he did not know that it would cause the patient to experience greatly increased blood pressure. So, if no one else knowingly did anything that contributed to the patient’s increase in blood pressure, no one other than Dr. Fitzpatrick is to blame for it.$batch09$, $batch09$Rule Not Triggered$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT144-S4-Q11$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$Any reasonable person could have foreseen that dropping a lit cigarette in dry leaves would start a fire. Thus, even if Kapp did not realize this, she is to blame for starting a fire on Rodriguez’s farm since she dropped a lit cigarette in dry leaves there.$batch09$, $batch09$Rule Not Triggered$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT144-S4-Q11$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT144-S4-Q11$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Rule$batch09$, $batch09$Two rules. (1) Someone who knowingly brings about misfortune should be blamed. (2) Someone who unwittingly brings about misfortune that they couldn't reasonably have foreseen should never be blamed.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$Notice the gap. If someone acted unwittingly but could have foreseen the misfortune, neither rule applies. Rule 1 needs knowledge, and rule 2 needs it to be unforeseeable. So the rules can only justify blaming a knowing actor, or not blaming an unwitting actor who couldn't have foreseen it.$batch09$), (2, $batch09$Goal$batch09$, $batch09$Someone unaware of the risk, who couldn't reasonably have foreseen it, shouldn't be blamed.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT144-S4-Q11$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$Riley would have realized it with a moment's thought, so the accident was foreseeable. Rule 2 doesn't apply, and no rule says Riley escapes blame.$batch09$), ($batch09$B$batch09$, $batch09$Oblicek had no idea the loan could bankrupt the business and couldn't reasonably have foreseen it. That's rule 2 exactly: unwitting and unforeseeable, so Oblicek should not be blamed.$batch09$), ($batch09$C$batch09$, $batch09$Gougon worried the sauce might make people sick but had no reason to think it would. Worry isn't knowledge, so rule 1 doesn't apply. No rule says Gougon should be blamed.$batch09$), ($batch09$D$batch09$, $batch09$The rules never say who is the only one to blame. And Dr. Fitzpatrick acted unknowingly, so rule 1 doesn't make the doctor blameworthy.$batch09$), ($batch09$E$batch09$, $batch09$This is the tempting one. Kapp should have seen the fire coming, and blaming Kapp feels right. But Kapp didn't realize it, so rule 1 (knowingly) doesn't apply. Rule 2 only excuses. No rule here blames someone who was unwitting but should have known.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT144-S4-Q11$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
